// CSD_RATIONALE_BEGIN
// Strategy:
// - Unconstrained phase: penalize "<<" to encourage initial reasoning without immediate expressions.
// - Constrained phase: adaptively control expression opening/closing using logit manipulation.
//   - Penalize ">>" when expressions are short to prevent premature closing.
//   - Boost ">>" when expressions are long to encourage closure.
//   - Use ConfidenceGatedStep to balance between model quality and grammar enforcement.
// CSD_RATIONALE_END

generated := [];
var steps := 0;
var insideConstrained := false;
var currentConstrained: Prefix := [];
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  invariant insideConstrained ==> forall t: Token ::
    t in parser.ValidNextTokens(currentConstrained) ==> t in lm.Tokens
  invariant helpers.cost == steps
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    // UNCONSTRAINED PHASE (RAW pattern):
    lm.GenerateLogits(prompt + generated);
    helpers.PenalizeTokenLogits(lm, ["<<"], 8.0);  // optional: delay expressions
    var next := lm.ChooseNextTokenUnconstrained();
    helpers.cost := helpers.cost + 1;
    if next == eosToken { break; }
    generated := generated + [next]; steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true; currentConstrained := [];
      CSDHelpers.RollbackPreservesTokenInvariant(lm, parser, []);
    }
  } else {
    // CONSTRAINED PHASE:
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 3);
    if narrow || parser.IsCompletePrefix(currentConstrained) {
      insideConstrained := false;
    } else {
      var next;
      if |currentConstrained| < 5 {
        // Penalize ">>" when short — prevents premature closing
        next := helpers.PenalizedConstrainedStep(lm, parser, prompt, currentConstrained, [">>"], 3.0);
      } else if |currentConstrained| >= 10 {
        // Boost ">>" when long — prevents runaway digit generation
        next := helpers.BoostedConstrainedStep(lm, parser, prompt, currentConstrained, [">>"], 50.0);
      } else {
        // Balance model quality and grammar enforcement
        next, _ := helpers.ConfidenceGatedStep(lm, parser, prompt, currentConstrained);
      }
      generated := generated + [next]; currentConstrained := currentConstrained + [next]; steps := steps + 1;
      if Contains(next, ">>") { insideConstrained := false; }
    }
  }
}
cost := helpers.cost;
